const useShapeDrag = (
    shape: IShape,
    shapes: IShape[],
    isSelected: boolean,
    tool: ToolType,
    updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void,
    setDraggingState: (isDragging: boolean) => void,
    selectedIds: string[],
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>,
    setAlignmentLines: (lines: AlignmentLine[]) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({ startPoint: new THREE.Vector3(), originalPositions: {} as Record<string, THREE.Vector3>, isDragging: false });
    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2((clientX / gl.domElement.clientWidth) * 2 - 1, -(clientY / gl.domElement.clientHeight) * 2 + 1);
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };
    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const rawDelta = new THREE.Vector3().subVectors(intersect, dragInfo.current.startPoint);
             const myOriginalPos = dragInfo.current.originalPositions[shape.id];
             if (!myOriginalPos) return;
             const targetPos = new THREE.Vector3().addVectors(myOriginalPos, rawDelta);
             let snappedX = Math.round(targetPos.x / SNAP_GRID) * SNAP_GRID;
             let snappedZ = Math.round(targetPos.z / SNAP_GRID) * SNAP_GRID;
             const newLines: AlignmentLine[] = [];
             const myBoundsRaw = getShapeBounds(shape, new THREE.Vector3(targetPos.x, myOriginalPos.y, targetPos.z));
             let bestXDist = 0.3; let bestXVal: number | null = null; let xMatchLine: AlignmentLine | null = null;
             let bestZDist = 0.3; let bestZVal: number | null = null; let zMatchLine: AlignmentLine | null = null;
             for (const other of shapes) {
                 if (selectedIds.includes(other.id)) continue;
                 const otherBounds = getShapeBounds(other);
                 const xSources = [myBoundsRaw.centerX, myBoundsRaw.minX, myBoundsRaw.maxX];
                 const xTargets = [otherBounds.centerX, otherBounds.minX, otherBounds.maxX];
                 for (const src of xSources) {
                     for (const tgt of xTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestXDist) { bestXDist = dist; bestXVal = targetPos.x - (src - tgt); const minZ = Math.min(myBoundsRaw.minZ, otherBounds.minZ) - 1; const maxZ = Math.max(myBoundsRaw.maxZ, otherBounds.maxZ) + 1; xMatchLine = [ new THREE.Vector3(tgt, 0, minZ), new THREE.Vector3(tgt, 0, maxZ) ]; }
                     }
                 }
                 const zSources = [myBoundsRaw.centerZ, myBoundsRaw.minZ, myBoundsRaw.maxZ];
                 const zTargets = [otherBounds.centerZ, otherBounds.minZ, otherBounds.maxZ];
                 for (const src of zSources) {
                     for (const tgt of zTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestZDist) { bestZDist = dist; bestZVal = targetPos.z - (src - tgt); const minX = Math.min(myBoundsRaw.minX, otherBounds.minX) - 1; const maxX = Math.max(myBoundsRaw.maxX, otherBounds.maxX) + 1; zMatchLine = [ new THREE.Vector3(minX, 0, tgt), new THREE.Vector3(maxX, 0, tgt) ]; }
                     }
                 }
             }
             if (bestXVal !== null) { snappedX = bestXVal; if (xMatchLine) newLines.push(xMatchLine); }
             if (bestZVal !== null) { snappedZ = bestZVal; if (zMatchLine) newLines.push(zMatchLine); }
             setAlignmentLines(newLines);
             const snappedPos = new THREE.Vector3(snappedX, myOriginalPos.y, snappedZ);
             const effectiveDelta = new THREE.Vector3().subVectors(snappedPos, myOriginalPos);
             Object.entries(dragInfo.current.originalPositions).forEach(([id, origPos]) => {
                 const ref = shapeRefs.current[id];
                 if (ref) { ref.position.copy(origPos).add(effectiveDelta); }
             });
        }
    }, [camera, gl, shape.id, shapes, selectedIds]);
    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setAlignmentLines([]);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        const updates = Object.keys(dragInfo.current.originalPositions).map(id => {
            const ref = shapeRefs.current[id];
            if (ref) { return { id, changes: { position: [ref.position.x, ref.position.y, ref.position.z] as [number, number, number] } }; }
            return null;
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];
        if (updates.length > 0) updateShapes(updates);
    }, [handlePointerMove, updateShapes, setDraggingState, setAlignmentLines]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.startPoint.copy(intersect);
            let idsToMove: string[] = [];
            if (isSelected) idsToMove = [...selectedIds]; else { if (shape.groupId) idsToMove = shapes.filter(s => s.groupId === shape.groupId).map(s => s.id); else idsToMove = [shape.id]; }
            if (!idsToMove.includes(shape.id)) idsToMove.push(shape.id);
            const origins: Record<string, THREE.Vector3> = {};
            idsToMove.forEach(id => { const ref = shapeRefs.current[id]; if (ref) origins[id] = ref.position.clone(); });
            dragInfo.current.originalPositions = origins;
            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, shapes, camera, gl, handlePointerMove, handlePointerUp, setDraggingState, isSelected, selectedIds]);
    useEffect(() => { return () => { window.removeEventListener('pointermove', handlePointerMove); window.removeEventListener('pointerup', handlePointerUp); }; }, [handlePointerMove, handlePointerUp]);
    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, pushPullState, pushPullHandlers, drawingHandlers, rotateHandlers, setDraggingState, onShapeRef, shapeRefs, setAlignmentLines }: ShapeRendererProps) => {
    const { unit, tool, updateShapes, layers, selectedIds, shapes, selectShape, updateShape } = useApp();
    const parentLayer = layers.find(l => l.id === shape.layerId);

    const handleSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        e.stopPropagation();
        const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey || e.nativeEvent.shiftKey;
        selectShape(shape.id, isMulti);
    }, [selectShape, shape.id]);

    const dimensionSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (!isSelected) {
             e.stopPropagation();
             selectShape(shape.id, e.nativeEvent.ctrlKey || e.nativeEvent.metaKey || e.nativeEvent.shiftKey);
        }
    }, [isSelected, selectShape, shape.id]);

    if (parentLayer && !parentLayer.visible) return null;

    if (shape.type === 'dimension') { 
        return <DimensionShape shape={shape} isSelected={isSelected} onSelect={dimensionSelect} />; 
    }

    if (shape.type === 'text') {
        const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

        useLayoutEffect(() => { 
            onShapeRef(shape.id, groupRef.current); 
            return () => onShapeRef(shape.id, null); 
        }, [onShapeRef, shape.id]);

        return (
            <group
                ref={groupRef}
                position={shape.position}
                rotation={new THREE.Euler(...shape.rotation)}
                scale={shape.scale}
                onClick={(e) => { 
                    if (tool === ToolType.SELECT) handleSelect(e);
                }}
                onPointerDown={(e) => {
                     if (tool === ToolType.SELECT) { if (!isSelected) handleSelect(e); handlePointerDown(e); }
                     else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                }}
            >
                <Text
                    fontSize={shape.fontSize || 0.5}
                    color={shape.color}
                    anchorX="center"
                    anchorY="middle"
                    outlineWidth={isSelected ? 0.02 : 0}
                    outlineColor="#3b82f6"
                >
                    {shape.content || 'Text'}
                </Text>
            </group>
        );
    }

    // Render Line Types specifically
    if (shape.type === 'line') {
         if (shape.points.length < 2) return null;
         if (!shape.points[0] || !shape.points[1]) return null;
         const p1 = transformPoint(shape.points[0], shape);
         const p2 = transformPoint(shape.points[1], shape);
         return (
             <group 
                position={[0, 0, 0]} // Lines are drawn in world space logic usually, or local. We will use transformPoint above which applies pos/rot.
                onClick={(e) => { 
                    if (tool === ToolType.SELECT) handleSelect(e);
                }}
             >
                <SimpleLine points={[p1, p2]} color={isSelected ? '#3b82f6' : 'black'} lineWidth={2} />
             </group>
         );
    }

    // GUARD: Ensure we have enough points for ExtrudeGeometry
    // This prevents "Cannot read properties of undefined (reading 'getPoint')" which occurs when ExtrudeGeometry receives invalid shapes (e.g., 0 curves)
    if (!shape.points || shape.points.length < 3) return null;

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = shape.color;
    const edgeColor = isSelected ? '#3b82f6' : '#333';
    const emissiveColor = isSelected ? '#3b82f6' : '#000000';
    const emissiveIntensity = isSelected ? 0.2 : 0;

    const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

    useLayoutEffect(() => { 
        onShapeRef(shape.id, groupRef.current); 
        return () => onShapeRef(shape.id, null); 
    }, [onShapeRef, shape.id]);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) scaleY = pushPullState.dragHeight / shape.height;

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const geometry = useMemo(() => new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false }), [shape2D, shape.height]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={new THREE.Euler(...shape.rotation)} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else if (tool === ToolType.SELECT) { if (!isSelected) handleSelect(e); handlePointerDown(e); }
                else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerMove(e);
                else if (tool === ToolType.ROTATE) rotateHandlers.handlePointerMove(e);
                else if (drawingHandlers.handlePointerMove) drawingHandlers.handlePointerMove(e);
            }}
            onPointerUp={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerUp(); else drawingHandlers.handlePointerUp(e); }}
        >
            <mesh 
                rotation={[-Math.PI/2, 0, 0]} 
                castShadow 
                receiveShadow 
                userData={{ isShape: true, id: shape.id }}
                geometry={geometry}
            >
                <meshStandardMaterial color={highlightColor} emissive={emissiveColor} emissiveIntensity={emissiveIntensity} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
                {!isPushPullMode && (
                    <lineSegments>
                        <edgesGeometry args={[geometry, 15]} />
                        <lineBasicMaterial color={edgeColor} toneMapped={false} />
                    </lineSegments>
                )}
            </mesh>
        </group>
    );
});

// ... Gizmo & Helper Components ...
const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void }> = ({ setDragging }) => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = (tool === ToolType.SELECT || tool === ToolType.ROTATE) && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    const activeMode = tool === ToolType.ROTATE ? 'rotate' : transformMode;
    useFrame(() => {
        if (!isEnabled || !selectedId) { if (targetObj) setTargetObj(null); return; }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => { if (found) return; if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) found = child; });
        if (found && found !== targetObj) setTargetObj(found);
    });
    if (!isEnabled || !targetObj) return null;
    return ( 
        <TransformControls 
            object={targetObj} 
            mode={activeMode} 
            space={activeMode === 'scale' ? 'local' : 'world'} 
            {...({ onDraggingChange: (isDragging: boolean) => { setDragging(isDragging); } } as any)}
            onMouseUp={() => { if (targetObj) updateShape(selectedId!, { position: [targetObj.position.x, targetObj.position.y, targetObj.position.z], rotation: [targetObj.rotation.x, targetObj.rotation.y, targetObj.rotation.z], scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z] }); }} 
        /> 
    );
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        const DISTANCE = 20;
        switch (view) { case 'top': targetPos.set(0, DISTANCE, 0); break; case 'bottom': targetPos.set(0, -DISTANCE, 0); break; case 'front': targetPos.set(0, 0, DISTANCE); break; case 'back': targetPos.set(0, 0, -DISTANCE); break; case 'right': targetPos.set(DISTANCE, 0, 0); break; case 'left': targetPos.set(-DISTANCE, 0, 0); break; default: return; }
        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) { const c = controls as any; if (c.target && typeof c.target.set === 'function') { c.target.set(0, 0, 0); c.update(); } }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

// ... Interaction Layer ...
const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; guideCreating: { active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }; drawingNormal: THREE.Vector3 }> = ({ tool, points, cursorPos, guideCreating, drawingNormal }) => {
    const { formatValue } = useApp();
    const currentPoint = cursorPos;
    if (tool === ToolType.GUIDE_LINE && guideCreating.active) {
        if (guideCreating.edge) {
            const p1 = guideCreating.edge[0]; const p2 = guideCreating.edge[1];
            const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
            const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
            const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));

            return ( 
                <group>
                    <SimpleLine points={[lineStart, lineEnd]} color="#a855f7" dashed opacity={0.6} />
                </group> 
            );
        } else if (tool === ToolType.GUIDE_LINE) {
            const dx = Math.abs(guideCreating.current.x - guideCreating.start.x);
            const dz = Math.abs(guideCreating.current.z - guideCreating.start.z);
            let start = guideCreating.start.clone();
            let end = guideCreating.current.clone();
            if (dx > dz) { end.z = start.z; start.x -= 100; end.x += 100; } else { end.x = start.x; start.z -= 100; end.z += 100; }
             return ( <group><SimpleLine points={[start, end]} color="#a855f7" dashed opacity={0.6} /></group> );
        }
    }

    if (tool === ToolType.DIMENSION && points.length > 0) {
        if (points.length === 1 && points[0]) {
            const start = new THREE.Vector3(points[0].x, points[0].y, points[0].z);
            const dist = start.distanceTo(currentPoint);
            return (
                <group>
                    <SimpleLine points={[start, currentPoint]} color="#3b82f6" dashed opacity={0.7} />
                    <Billboard position={[currentPoint.x, currentPoint.y + 0.3, currentPoint.z]}>
                         <Text fontSize={0.25} color="#3b82f6" depthTest={false}>
                            {formatValue(dist)}
                         </Text>
                    </Billboard>
                </group>
            );
        }

        if (points.length === 2 && points[0] && points[1]) {
             const p1 = new THREE.Vector3(points[0].x, points[0].y, points[0].z);
             const p2 = new THREE.Vector3(points[1].x, points[1].y, points[1].z);
             const p3 = currentPoint.clone();

             // PLANE INFERENCE FIX:
             // If P1 and P2 are at the same height (horizontal edge), lock P3 to that height.
             // This visual constraint ensures the preview line stays parallel to the edge
             // even if the cursor raycast hits the floor.
             if (Math.abs(p1.y - p2.y) < 0.05) {
                p3.y = p1.y;
             }

             const v12 = new THREE.Vector3().subVectors(p2, p1);
             const v13 = new THREE.Vector3().subVectors(p3, p1);
             const lenSq = v12.lengthSq();
             const projectionFactor = lenSq > 0 ? v13.dot(v12) / lenSq : 0;
             const projectedPoint = p1.clone().add(v12.clone().multiplyScalar(projectionFactor));

             const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);

             const dimStart = p1.clone().add(offsetVector);
             const dimEnd = p2.clone().add(offsetVector);
             const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);

             const GAP_SIZE = 0.05; 
             const offsetDir = offsetVector.clone().normalize();
             const offsetLen = offsetVector.length();

             const useGap = offsetLen > GAP_SIZE * 1.5;
             const ext1Start = useGap ? p1.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p1;
             const ext2Start = useGap ? p2.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p2;
             const color = "#3b82f6";

             return (
                <group>
                    <SimpleLine points={[dimStart, dimEnd]} color={color} opacity={0.8} />
                    <SimpleLine points={[ext1Start, dimStart]} color="#999" dashed opacity={0.5} />
                    <SimpleLine points={[ext2Start, dimEnd]} color="#999" dashed opacity={0.5} />
                    <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
                    <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
                    <Billboard position={midPoint}>
                        <Text 
                            fontSize={0.25} 
                            color={color} 
                            anchorX="center" 
                            anchorY="middle" 
                            outlineWidth={0.02} 
                            outlineColor="#ffffff" 
                            depthTest={false}
                            renderOrder={1000}
                        >
                            {formatValue(p1.distanceTo(p2))}
                        </Text>
                    </Billboard>
                </group>
             );
        }
    }

    if (points.length === 0) return null;
    const startPoint = points[points.length-1];
    if (!startPoint) return null;
    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) { 
        return <SimpleLine points={[startVec, currentPoint]} color="black" dashed />; 
    }

    if (tool === ToolType.DRAW_RECT) {
        const start = points[0];
        if (!start) return null;
        const startV = new THREE.Vector3(start.x, start.y, start.z);
        const { right, top } = getLocalBasis(drawingNormal);
        const diff = new THREE.Vector3().subVectors(currentPoint, startV);
        const w = diff.dot(right); 
        const h = diff.dot(top);

        const p1 = startV;
        const p2 = startV.clone().add(right.clone().multiplyScalar(w));
        const p3 = startV.clone().add(right.clone().multiplyScalar(w)).add(top.clone().multiplyScalar(h));
        const p4 = startV.clone().add(top.clone().multiplyScalar(h));
        const rectPoints = [p1, p2, p3, p4, p1];

        const widthMid = p1.clone().add(right.clone().multiplyScalar(w / 2));
        const heightMid = p2.clone().add(top.clone().multiplyScalar(h / 2));

        return (
            <group>
                <SimpleLine points={rectPoints} color="black" dashed />
                <Billboard position={[widthMid.x, widthMid.y + 0.1, widthMid.z]}>
                    <Text fontSize={0.25} color="#000" depthTest={false}>
                        {formatValue(Math.abs(w))}
                    </Text>
                </Billboard>
                 <Billboard position={[heightMid.x, heightMid.y + 0.1, heightMid.z]}>
                    <Text fontSize={0.25} color="#000" depthTest={false}>
                        {formatValue(Math.abs(h))}
                    </Text>
                </Billboard>
            </group>
        );
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const start = points[0];
        if (!start) return null;
        const startV = new THREE.Vector3(start.x, start.y, start.z);
        const radius = startV.distanceTo(currentPoint);
        const circlePts = createCirclePoints(radius);
        const worldPts = circlePts.map(p => new THREE.Vector3(p.x + startV.x, p.y + startV.y, p.z + startV.z)); 
        return (
            <group>
                <SimpleLine points={worldPts} color="black" dashed />
                <SimpleLine points={[startV, currentPoint]} color="gray" dashed />
            </group>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
    guideCreating: any;
    rotateState: RotateState;
    drawingNormal: THREE.Vector3;
    isGizmoDragging: boolean;
    inferenceGuide: InferenceGuide | null;
    setInferenceGuide: (g: InferenceGuide | null) => void;
    onPointerDown?: (e: ThreeEvent<PointerEvent>) => void;
    onPointerUp?: (e: ThreeEvent<PointerEvent>) => void;
    onClick?: (e: ThreeEvent<MouseEvent>) => void;
    onMove?: (e: ThreeEvent<PointerEvent>) => void;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput, guideCreating, rotateState, drawingNormal, isGizmoDragging, inferenceGuide, setInferenceGuide, onPointerDown, onPointerUp, onClick, onMove }) => {
    const { formatValue } = useApp();

    let inputBox = null;
    if (tool === ToolType.DRAW_LINE && drawPoints.length > 0) {
        const start = drawPoints[drawPoints.length - 1];
        if (start) {
            const startVec = new THREE.Vector3(start.x, start.y, start.z);
            const dist = startVec.distanceTo(cursorPos);
            const displayVal = typedInput ? typedInput : formatValue(dist);
            inputBox = <DynamicInputBox position={cursorPos} label="長度" value={displayVal} isTyping={!!typedInput} />;
        }
    } else if (tool === ToolType.GUIDE_LINE && guideCreating.active) {
        let dist = 0;
        if (guideCreating.edge) {
             const p1 = guideCreating.edge[0]; const p2 = guideCreating.edge[1]; 
             const edgeVec = new THREE.Vector3().subVectors(p2, p1); 
             const pointVec = new THREE.Vector3().subVectors(cursorPos, p1); 
             const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq())); 
             dist = cursorPos.distanceTo(projected);
        } else {
             const dx = Math.abs(cursorPos.x - guideCreating.start.x);
             const dz = Math.abs(cursorPos.z - guideCreating.start.z);
             dist = dx > dz ? dx : dz;
        }
        const displayVal = typedInput ? typedInput : formatValue(dist);
        inputBox = <DynamicInputBox position={cursorPos} label="距離" value={displayVal} isTyping={!!typedInput} />;
    }

    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                onPointerMove={onMove}
                onPointerDown={onPointerDown}
                onPointerUp={onPointerUp}
                onClick={onClick}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial visible={false} />
            </mesh>
             {snapInfo && tool !== ToolType.ROTATE && !isGizmoDragging && ( <><SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} /><CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} /></> )}
             <InferenceGuideRenderer guide={inferenceGuide} />
             <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} guideCreating={guideCreating} drawingNormal={drawingNormal} />
             {inputBox}
        </group>
    );
};

const usePushPullManager = () => {
    const { tool, updateShape, shapes, setMeasurement, formatValue, layers } = useApp();
    const { camera, gl } = useThree();
    const [ppState, setPPState] = useState<PushPullState>({ mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, dragStartPoint: null, originalHeight: 0, originalPoints: [], normal: new THREE.Vector3(0, 1, 0), dragHeight: undefined });
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };
    const isDragging = !!ppState.dragStartPoint;
    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const intersection = (e.intersections as unknown as THREE.Intersection[]).find(i => i.face && (i.object.userData?.isShape || i.object.parent?.userData?.isShape));
        if (!intersection || !intersection.face) return null;
        const object = intersection.object;
        let shapeId: string | null = null;
        if (object.userData?.isShape) shapeId = object.userData.id; else if (object.parent?.userData?.isShape) shapeId = object.parent.userData.id;
        if (!shapeId) return null;
        const shape = shapes.find(s => s.id === shapeId);
        if (!shape) return null;
        const layer = layers.find(l => l.id === shape.layerId);
        if (layer && !layer.visible) return null;
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        if (worldNormal.y > 0.9) return { mode: 'top', hoveredShapeId: shapeId, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, 1, 0) };
        if (worldNormal.y < -0.9) return { mode: 'none', hoveredShapeId: null, hoveredEdgeIndex: -1, normal: new THREE.Vector3(0, -1, 0) }; 
        if (Math.abs(worldNormal.y) < 0.2) {
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation));
            const invQuat = shapeQuat.clone().invert();
            const localPoint = hitPoint.applyQuaternion(invQuat);
            const xLocal = localPoint.x; const zLocal = localPoint.z;
            let closestIndex = -1; let minDistSq = Infinity;
            const pts = shape.points;
            if (!pts) return null;
            for(let i=0; i<pts.length; i++) { 
                const p1 = pts[i]; 
                const p2 = pts[(i+1) % pts.length]; 
                if (!p1 || !p2) continue;
                const unscaledX = xLocal / shape.scale[0]; 
                const unscaledZ = zLocal / shape.scale[2]; 
                const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z)); if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; } }
            if (closestIndex !== -1) { const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize(); return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal }; }
        }
        return null;
    }, [shapes, layers]);
    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;
        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
            if (ppState.mode === 'top') { const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint); const target = new THREE.Vector3(); raycaster.ray.intersectPlane(dragPlane, target); if (target) { const deltaY = target.y - ppState.dragStartPoint.y; const newHeight = Math.max(0.01, ppState.originalHeight + deltaY); setPPState(prev => ({ ...prev, dragHeight: newHeight })); setMeasurement(`高度: ${formatValue(newHeight)}`); } } 
            else if (ppState.mode === 'side') { const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); const target = new THREE.Vector3(); raycaster.ray.intersectPlane(dragPlane, target); if (target) { const diff = target.clone().sub(ppState.dragStartPoint); const projection = diff.dot(ppState.normal); const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection); setMeasurement(`偏移: ${formatValue(projection)}`); const shapeQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(...shape.rotation)); const invQuat = shapeQuat.clone().invert(); const moveVectorLocal = moveVectorWorld.clone().applyQuaternion(invQuat); const dLocalX = moveVectorLocal.x / shape.scale[0]; const dLocalZ = moveVectorLocal.z / shape.scale[2]; const idx = ppState.hoveredEdgeIndex; const newPoints = ppState.originalPoints.map(p => ({...p})); const p1 = newPoints[idx]; const p2 = newPoints[(idx+1) % newPoints.length]; p1.x += dLocalX; p1.z += dLocalZ; p2.x += dLocalX; p2.z += dLocalZ; const updatedShape = { ...shape, points: newPoints }; setTempShape(updatedShape); } }
        } else {
            const res = identifyFace(e);
            if (res) { e.stopPropagation(); document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize'; setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! })); } 
            else { setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null })); document.body.style.cursor = 'default'; }
        }
    }, [tool, isDragging, ppState, shapes, camera, gl, identifyFace, setMeasurement, formatValue]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();
        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;
             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);
             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') { const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), (e as any).point); raycaster.ray.intersectPlane(plane, startPoint); } 
             else { const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); raycaster.ray.intersectPlane(plane, startPoint); }
             setPPState(prev => ({ ...prev, dragStartPoint: startPoint, originalHeight: shape.height, dragHeight: shape.height, originalPoints: JSON.parse(JSON.stringify(shape.points)) }));
             if (ppState.mode === 'side') setTempShape(shape);
        }
    }, [tool, ppState, shapes, camera, gl]);
    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'top' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) { const shape = shapes.find(s => s.id === ppState.hoveredShapeId); const updates: Partial<IShape> = { height: ppState.dragHeight }; if (shape && shape.type === 'flat' && ppState.dragHeight > 0.05) { updates.type = 'solid'; if (shape.color === FLAT_COLOR) updates.color = DEFAULT_COLOR; } updateShape(ppState.hoveredShapeId, updates); } 
        else if (tempShapeRef.current) { updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points }); }
        setTempShape(null); setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined })); setMeasurement('');
    }, [updateShape, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId, shapes, setMeasurement]);
