    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const useRotateManager = (shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>) => {
    const { tool, shapes, updateShapes, selectedIds } = useApp();
    const { camera, gl } = useThree();
    const [rotateState, setRotateState] = useState<RotateState>({
        phase: 'hover',
        pivot: null,
        axis: null,
        startVector: null,
        currentAngle: 0,
        initialTransforms: {},
        lockedAxis: null
    });

    useEffect(() => {
        if (tool !== ToolType.ROTATE) {
            setRotateState({
                phase: 'hover',
                pivot: null,
                axis: null,
                startVector: null,
                currentAngle: 0,
                initialTransforms: {},
                lockedAxis: null
            });
        }
    }, [tool]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool !== ToolType.ROTATE) return;
        e.stopPropagation();

        if (rotateState.phase === 'hover') {
             const point = e.point.clone();
             const initials: Record<string, {pos: THREE.Vector3, quat: THREE.Quaternion}> = {};
             shapes.filter(s => selectedIds.includes(s.id)).forEach(s => {
                 const obj = new THREE.Object3D();
                 obj.position.set(...s.position);
                 obj.rotation.set(...s.rotation);
                 obj.scale.set(...s.scale);
                 initials[s.id] = { pos: obj.position.clone(), quat: obj.quaternion.clone() };
             });

             setRotateState(prev => ({
                 ...prev,
                 phase: 'set-start',
                 pivot: point,
                 initialTransforms: initials
             }));
        } else if (rotateState.phase === 'set-start') {
             const current = e.point.clone();
             if (rotateState.pivot) {
                 const startVec = new THREE.Vector3().subVectors(current, rotateState.pivot).normalize();
                 setRotateState(prev => ({
                     ...prev,
                     phase: 'rotating',
                     startVector: startVec,
                     currentAngle: 0
                 }));
             }
        } else if (rotateState.phase === 'rotating') {
             if (rotateState.pivot && rotateState.startVector) {
                 const angle = rotateState.currentAngle;
                 const updates = Object.keys(rotateState.initialTransforms).map(id => {
                     const init = rotateState.initialTransforms[id];
                     const pivot = rotateState.pivot!;

                     const v = new THREE.Vector3().subVectors(init.pos, pivot);
                     v.applyAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                     const newPos = new THREE.Vector3().addVectors(pivot, v);

                     const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                     q.multiply(init.quat);
                     const newEuler = new THREE.Euler().setFromQuaternion(q);

                     return { 
                         id, 
                         changes: { 
                             position: [newPos.x, newPos.y, newPos.z] as [number, number, number],
                             rotation: [newEuler.x, newEuler.y, newEuler.z] as [number, number, number]
                         } 
                     };
                 });
                 updateShapes(updates);
             }
             setRotateState(prev => ({ ...prev, phase: 'hover', pivot: null, startVector: null, currentAngle: 0 }));
        }
    }, [tool, rotateState, selectedIds, shapes, updateShapes]);

    const handleRotateMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.ROTATE) return;
        const current = e.point.clone();

        if (rotateState.phase === 'rotating' && rotateState.pivot && rotateState.startVector) {
             const currVec = new THREE.Vector3().subVectors(current, rotateState.pivot).normalize();
             let angle = Math.atan2(currVec.z, currVec.x) - Math.atan2(rotateState.startVector.z, rotateState.startVector.x);

             if (e.shiftKey) {
                 const SNAP = Math.PI / 12; // 15 deg
                 angle = Math.round(angle / SNAP) * SNAP;
             }

             setRotateState(prev => ({ ...prev, currentAngle: angle }));

             Object.keys(rotateState.initialTransforms).forEach(id => {
                 const ref = shapeRefs.current[id];
                 if (!ref) return;

                 const init = rotateState.initialTransforms[id];
                 const pivot = rotateState.pivot!;

                 const v = new THREE.Vector3().subVectors(init.pos, pivot);
                 v.applyAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                 const newPos = new THREE.Vector3().addVectors(pivot, v);

                 const q = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle);
                 q.multiply(init.quat);

                 ref.position.copy(newPos);
                 ref.quaternion.copy(q);
             });
        }
    }, [tool, rotateState, shapeRefs]);

    return { rotateState, handleRotateMove, handleClick };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes, updateShape, setMeasurement, activeLayerId, addGuideLine, removeShape, unit } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [drawingHeight, setDrawingHeight] = useState(0);
    const [typedInput, setTypedInput] = useState('');
    const [drawingNormal, setDrawingNormal] = useState<THREE.Vector3>(new THREE.Vector3(0, 1, 0));
    const [guideCreation, setGuideCreation] = useState<{ active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }>({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
    const [inferenceGuide, setInferenceGuide] = useState<InferenceGuide | null>(null);
    const currentChainIds = useRef<string[]>([]); 

    useEffect(() => { 
        setDrawPoints([]); setSnapInfo(null); setIsDragging(false); setDrawingHeight(0); setMeasurement(''); setTypedInput(''); setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setDrawingNormal(new THREE.Vector3(0, 1, 0)); setInferenceGuide(null); currentChainIds.current = [];
    }, [tool, setMeasurement]);

    const attemptGeometryCut = useCallback((p1: THREE.Vector3, p2: THREE.Vector3) => {
        let cutOccurred = false;
        const start = { x: p1.x, y: 0, z: p1.z };
        const end = { x: p2.x, y: 0, z: p2.z };

        const flatShapes = shapes.filter(s => (s.type === 'flat' || s.type === 'solid') && s.name !== 'Edge');
        const idsToRemove = new Set<string>();
        const shapesToAddList: IShape[] = [];

        for (const shape of flatShapes) {
             if (idsToRemove.has(shape.id)) continue;
             if (Math.abs(shape.position[1] - p1.y) > 0.1) continue;

             const worldPoints = shape.points.map(p => {
                 const wp = transformPoint(p, shape);
                 return { x: wp.x, y: 0, z: wp.z };
             });

             const splitResult = cutPolygonBySegment(worldPoints, start, end);
             if (splitResult) {
                 const [polyA, polyB] = splitResult;
                 const createFragment = (points: IPoint[], suffix: string) => {
                     let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
                     points.forEach(p => { 
                         if (!p) return;
                         if(p.x < minX) minX = p.x; 
                         if(p.x > maxX) maxX = p.x; 
                         if(p.z < minZ) minZ = p.z; 
                         if(p.z > maxZ) maxZ = p.z; 
                     });
                     const cx = (minX + maxX) / 2;
                     const cz = (minZ + maxZ) / 2;
                     const localPoints = points.filter(p => !!p).map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));

                     return {
                         ...shape,
                         id: `split-${Date.now()}-${suffix}`,
                         points: localPoints,
                         position: [cx, shape.position[1], cz] as [number, number, number],
                         rotation: [0, 0, 0] as [number, number, number], 
                         scale: [1, 1, 1] as [number, number, number],
                         name: shape.name
                     };
                 };

                 shapesToAddList.push(createFragment(polyA, 'A'));
                 shapesToAddList.push(createFragment(polyB, 'B'));
                 idsToRemove.add(shape.id);
                 cutOccurred = true;
             }
        }

        if (cutOccurred) {
            replaceShapes(Array.from(idsToRemove), shapesToAddList);
        }
    }, [shapes, replaceShapes]);

    const addPoint = useCallback((point: THREE.Vector3) => {
        if (drawPoints.length > 0) {
            const start = drawPoints[0];
            const dist = point.distanceTo(new THREE.Vector3(start.x, start.y, start.z));

            if (dist < SNAP_THRESHOLD) {
                const finalPoints = [...drawPoints];
                const idsToRemove = [...currentChainIds.current];
                currentChainIds.current = [];
                const createShapeObj = (base: Partial<IShape>): IShape => ({ ...base as IShape, layerId: activeLayerId });
                let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
                finalPoints.forEach(p => { if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x; if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z; });
                const cx = (minX + maxX) / 2; const cz = (minZ + maxZ) / 2;
                const localPoints = finalPoints.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));

                const newFace = createShapeObj({
                    id: `face-${Date.now()}`,
                    type: 'flat',
                    name: '平面',
                    points: localPoints,
                    height: DEFAULT_HEIGHT,
                    color: FLAT_COLOR,
                    position: [cx, finalPoints[0].y, cz],
                    rotation: [0, 0, 0],
                    scale: [1, 1, 1]
                });

                replaceShapes(idsToRemove, [newFace]);
                setDrawPoints([]);
                setMeasurement('已建立平面');
                return;
            }
        }

        const newPoint = { x: point.x, y: point.y, z: point.z };
        const newPointsList = [...drawPoints, newPoint];
        setDrawPoints(newPointsList);

        if (tool === ToolType.DRAW_LINE) {
            if (drawPoints.length > 0) {
                const prev = drawPoints[drawPoints.length - 1];
                if (prev) {
                    const p1 = new THREE.Vector3(prev.x, prev.y, prev.z);
                    const p2 = point;
                    const createShapeObj = (base: Partial<IShape>): IShape => ({ ...base as IShape, layerId: activeLayerId });
                    const lineId = `line-${Date.now()}-${Math.random()}`;
                    const lineShape: IShape = {
                        id: lineId,
                        layerId: activeLayerId,
                        type: 'line',
                        name: '直線',
                        points: [{ x: 0, y: 0, z: 0 }, { x: p2.x - p1.x, y: p2.y - p1.y, z: p2.z - p1.z }], 
                        position: [p1.x, p1.y, p1.z],
                        rotation: [0, 0, 0],
                        scale: [1, 1, 1],
                        height: 0,
                        color: '#000000'
                    };
                    addShape(lineShape);
                    currentChainIds.current.push(lineId);
                    attemptGeometryCut(p1, p2);
                }
            }
        }

    }, [drawPoints, tool, activeLayerId, addShape, replaceShapes, attemptGeometryCut]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        if (tool === ToolType.DRAW_LINE) {
            setDrawPoints([]);
            return;
        }

        const createShapeObj = (base: Partial<IShape>): IShape => ({ ...base as IShape, layerId: activeLayerId });
        const { right, top, normal } = getLocalBasis(drawingNormal);
        const rotationMatrix = new THREE.Matrix4().makeBasis(right, normal, top);
        const quaternion = new THREE.Quaternion().setFromRotationMatrix(rotationMatrix);
        const euler = new THREE.Euler().setFromQuaternion(quaternion);

        // Guard against empty points
        if (finalPoints.length === 0 || !finalPoints[0]) {
             setDrawPoints([]);
             return;
        }

        const startPoint = new THREE.Vector3(finalPoints[0].x, finalPoints[0].y, finalPoints[0].z);
        const newShapeBase: Partial<IShape> = { height: DEFAULT_HEIGHT, color: FLAT_COLOR, rotation: [euler.x, euler.y, euler.z], scale: [1, 1, 1] };
        let newShapePoints: IPoint[] = [];

        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const endPt = finalPoints[finalPoints.length - 1];
             if (endPt) {
                 const endPoint = new THREE.Vector3(endPt.x, endPt.y, endPt.z);
                 const diff = new THREE.Vector3().subVectors(endPoint, startPoint);
                 const width = diff.dot(right); const depth = diff.dot(top);
                 if (Math.abs(width) >= 0.01 && Math.abs(depth) >= 0.01) {
                     const worldCenter = startPoint.clone().add(right.clone().multiplyScalar(width / 2)).add(top.clone().multiplyScalar(depth / 2));
                     const halfW = Math.abs(width) / 2; const halfD = Math.abs(depth) / 2;
                     newShapePoints = [ { x: -halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: -halfD } ];
                     newShapeBase.id = `rect-${Date.now()}`; newShapeBase.type = 'flat'; newShapeBase.name = '矩形'; newShapeBase.position = [worldCenter.x, worldCenter.y, worldCenter.z];
                 }
             }
        } else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
            if (finalPoints[1]) {
                const endPoint = new THREE.Vector3(finalPoints[1].x, finalPoints[1].y, finalPoints[1].z);
                const radius = startPoint.distanceTo(endPoint);
                if (radius > 0.01) { newShapePoints = createCirclePoints(radius); newShapeBase.id = `circle-${Date.now()}`; newShapeBase.type = 'flat'; newShapeBase.name = '圓形'; newShapeBase.position = [startPoint.x, startPoint.y, startPoint.z]; }
            }
        } else if (tool === ToolType.DIMENSION && finalPoints.length >= 3) {
            // Filter undefined points
            const validPoints = finalPoints.filter(p => !!p);
            if (validPoints.length >= 3) {
                newShapePoints = [validPoints[0], validPoints[1], validPoints[2]]; 
                newShapeBase.id = `dim-${Date.now()}`; 
                newShapeBase.type = 'dimension'; 
                newShapeBase.name = '尺寸標註'; 
                newShapeBase.color = '#333';
                newShapeBase.position = [0, 0, 0]; 
            }
        }

        if (newShapePoints.length > 0) {
             const finalNewShape: IShape = createShapeObj({ ...newShapeBase as IShape, points: newShapePoints });
             addShape(finalNewShape);
        }

        setDrawPoints([]); 
        if (tool !== ToolType.DIMENSION) setTool(ToolType.SELECT); 
        setMeasurement(''); 
        setTypedInput('');

    }, [tool, addShape, activeLayerId, drawingNormal, setTool, setMeasurement]);

    const handleInputSubmit = useCallback(() => {
        if (!typedInput || drawPoints.length === 0) return;
        const start = drawPoints[drawPoints.length - 1]; 
        if (!start) return;

        const startVec = new THREE.Vector3(start.x, start.y, start.z); const cursorVec = cursorPos.clone();
        let targetVec = new THREE.Vector3(); const direction = cursorVec.clone().sub(startVec).normalize();

        const scaleFactor = unit === 'cm' ? 0.01 : 1;

        if (tool === ToolType.DRAW_RECT) { 
            const parts = typedInput.split(/[, ]+/).filter(p => p.trim() !== '').map(parseFloat); 
            if (parts.length > 0 && !parts.some(isNaN)) { 
                const val = parts[0] * scaleFactor; 
                targetVec = startVec.clone().add(direction.multiplyScalar(val)); 
            } 
        } else { 
            let val = parseFloat(typedInput); 
            if (isNaN(val)) return; 
            val = val * scaleFactor;

            if (cursorVec.distanceTo(startVec) < 0.001) { direction.set(1, 0, 0); } 
            targetVec = startVec.clone().add(direction.multiplyScalar(val)); 
        }

        if (tool === ToolType.DRAW_LINE) {
            addPoint(targetVec);
            setTypedInput('');
        } else {
            const finalPoints = [...drawPoints, { x: targetVec.x, y: targetVec.y, z: targetVec.z }]; 
            finishShape(finalPoints);
        }
    }, [typedInput, drawPoints, cursorPos, tool, finishShape, addPoint, unit]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE) return;
        if (e.button !== 0) return;
        e.stopPropagation();
        setTypedInput('');
        const pt = snapInfo ? snapInfo.position.clone() : (e as any).point.clone();
        setCursorPos(pt.clone());
        if (drawPoints.length === 0) { if (snapInfo && (snapInfo.type === 'face' || snapInfo.type === 'vertex' || snapInfo.type === 'edge') && snapInfo.normal) setDrawingNormal(snapInfo.normal.clone()); else setDrawingNormal(new THREE.Vector3(0, 1, 0)); }

        if (tool === ToolType.GUIDE_LINE && snapInfo && snapInfo.type === 'edge' && snapInfo.snapEdge) { 
             setIsDragging(true); 
             setGuideCreation({ active: true, start: pt.clone(), current: pt.clone(), edge: snapInfo.snapEdge }); 
             return; 
        }

        if (tool === ToolType.GUIDE_LINE) {
            setIsDragging(true);
            setGuideCreation({ active: true, start: pt.clone(), current: pt.clone(), edge: null });
            return;
        }

        setIsDragging(true);

        if (tool === ToolType.DRAW_LINE) {
            addPoint(pt);
        } else {
            if (drawPoints.length === 0) { setDrawPoints([{ x: pt.x, y: pt.y, z: pt.z }]); if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]); } 
            else if (tool === ToolType.DIMENSION) setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
        }
    }, [tool, drawPoints, snapInfo, addPoint]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE) return;
        setIsDragging(false);

        if (tool === ToolType.GUIDE_LINE && guideCreation.active) {
            if (guideCreation.edge) {
                const p1 = guideCreation.edge![0]; 
                const p2 = guideCreation.edge![1]; 
                const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
                const lineStart = guideCreation.current.clone();
                const lineEnd = guideCreation.current.clone().add(direction);
                addGuideLine({ id: `guide-${Date.now()}`, points: [ [lineStart.x, lineStart.y, lineStart.z], [lineEnd.x, lineEnd.y, lineEnd.z] ] });
            } else if (tool === ToolType.GUIDE_LINE && !guideCreation.edge) {
                const dx = Math.abs(guideCreation.current.x - guideCreation.start.x);
                const dz = Math.abs(guideCreation.current.z - guideCreation.start.z);
                let start = guideCreation.start.clone();
                let end = guideCreation.start.clone();
                if (dx > dz) { end.x += 1; } else { end.z += 1; }
                addGuideLine({ id: `guide-axis-${Date.now()}`, points: [ [start.x, start.y, start.z], [end.x, end.y, end.z] ] });
            }
            setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); 
            setMeasurement(''); 
            return;
        }

        if (tool === ToolType.DRAW_TEXT) {
             const newShape: IShape = {
                id: `text-${Date.now()}`,
                layerId: activeLayerId,
                type: 'text',
                name: '文字說明',
                points: [{ x: 0, y: 0, z: 0 }],
                position: [cursorPos.x, cursorPos.y, cursorPos.z],
                rotation: [-Math.PI/2, 0, 0], 
                scale: [1, 1, 1],
                height: 0,
                color: '#000000',
                content: '文字',
                fontSize: 0.5
            };
            addShape(newShape);
            setTool(ToolType.SELECT);
            return;
        }

        if (tool === ToolType.DIMENSION) { 
            if (drawPoints.length >= 3) finishShape([...drawPoints]); 
            return; 
        }

        if ((tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE) && drawPoints.length >= 2) { const points = [...drawPoints]; points[points.length-1] = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z }; finishShape(points); }
    }, [tool, drawPoints, cursorPos, finishShape, guideCreation, addGuideLine, setMeasurement, activeLayerId, addShape, setTool]);

    useEffect(() => { if (guideCreation.active) setGuideCreation(prev => ({ ...prev, current: cursorPos.clone() })); }, [cursorPos, guideCreation.active]);
    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {}, []);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
             if ([ToolType.SELECT, ToolType.PUSH_PULL, ToolType.ROTATE].includes(tool)) return;
             if (e.key === 'Escape') {
                 setDrawPoints([]);
                 setTypedInput('');
                 setMeasurement('');
                 if (tool === ToolType.GUIDE_LINE) {
                     setGuideCreation({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
                 }
             }
             if (e.key === 'Enter') {
                 if (drawPoints.length > 0) handleInputSubmit();
             }
             if (e.key === 'Backspace' && document.activeElement === document.body) {
                if (typedInput.length > 0) {
                     setTypedInput(prev => prev.slice(0, -1));
                } else if(drawPoints.length > 0) {
                    setDrawPoints(prev => prev.slice(0, -1));
                }
             }
             if ((e.key >= '0' && e.key <= '9') || e.key === '.' || e.key === ',') {
                 if (document.activeElement === document.body) {
                     setTypedInput(prev => prev + e.key);
                 }
             }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, drawPoints, typedInput, handleInputSubmit, setMeasurement, guideCreation]);

    return { 
        drawPoints, 
        cursorPos, 
        snapInfo, 
        setCursorPos, 
        setSnapInfo, 
        handlePointerDown, 
        handlePointerUp, 
        handleClick,
        isDragging,
        drawingHeight,
        typedInput,
        guideCreation,
        drawingNormal,
        inferenceGuide,
        setInferenceGuide
    };
};

const SceneContent: React.FC = () => {
  const { 
    shapes, 
    tool, 
    gridSize, 
    selectedIds, 
    removeSelected, 
    currentView, 
    setCurrentView,
    updateShapes,
    setTransformMode,
    guideLines,
    layers
  } = useApp();

  const [isGizmoDragging, setGizmoDragging] = useState(false);
  const shapeRefs = useRef<Record<string, THREE.Group | null>>({});
  const [alignmentLines, setAlignmentLines] = useState<AlignmentLine[]>([]);

  const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, isDragging: isPPDragging, tempShape: ppTempShape } = usePushPullManager();
  const { rotateState, handleRotateMove, handleClick: handleRotateClick } = useRotateManager(shapeRefs);
  const drawingManager = useDrawingManager();

  const handleShapeRef = useCallback((id: string, ref: THREE.Group | null) => {
      if (ref) shapeRefs.current[id] = ref;
      else delete shapeRefs.current[id];
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
       if (e.key === 'Delete' || e.key === 'Backspace') {
           if (tool === ToolType.SELECT && selectedIds.length > 0 && !drawingManager.typedInput) {
               removeSelected();
           }
       }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [tool, selectedIds, removeSelected, drawingManager.typedInput]);

  useEffect(() => {
      if (tool === ToolType.SELECT) document.body.style.cursor = 'default';
      else if (tool === ToolType.PUSH_PULL) document.body.style.cursor = 'default';
      else if (tool === ToolType.ROTATE) document.body.style.cursor = rotateState.phase === 'rotating' ? 'grabbing' : 'alias';
      else document.body.style.cursor = 'crosshair';
  }, [tool, rotateState.phase]);

  const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
      if (isPPDragging) { handlePPMove(e); return; }
      if (rotateState.phase === 'rotating') { handleRotateMove(e); return; }
      if (isGizmoDragging) return;

      if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DIMENSION, ToolType.GUIDE_LINE, ToolType.DRAW_TEXT].includes(tool)) {
          const ray = e.ray;
          let candidatePos = e.point.clone(); 

          // --- Plane Inference Logic ---
          let inferredPlane: THREE.Plane | null = null;

          // 1. Dimension Tool - 3rd point placement (Offset)
          if (tool === ToolType.DIMENSION && drawingManager.drawPoints.length === 2) {
              const p1 = drawingManager.drawPoints[0];
              const p2 = drawingManager.drawPoints[1];
              if (p1 && p2 && Math.abs(p1.y - p2.y) < 0.05) { // Check horizontal alignment
                  inferredPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -p1.y);
              }
          } 

          // 2. Guide Line Tool - Dragging
          if (tool === ToolType.GUIDE_LINE && drawingManager.guideCreation.active) {
               if (drawingManager.guideCreation.edge) {
                    const p1 = drawingManager.guideCreation.edge[0];
                    const p2 = drawingManager.guideCreation.edge[1];
                    if (p1 && p2 && Math.abs(p1.y - p2.y) < 0.05) {
                        inferredPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -p1.y);
                    }
               } else if (drawingManager.guideCreation.start) {
                    inferredPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -drawingManager.guideCreation.start.y);
               }
          }

          // If a plane is inferred, project the ray onto it to override ground fallback
          if (inferredPlane) {
              const planeIntersect = new THREE.Vector3();
              if (ray.intersectPlane(inferredPlane, planeIntersect)) {
                  candidatePos = planeIntersect;
              }
          }

          // Pass candidatePos (potentially corrected by plane) to snap logic
          const snap = getGeometrySnap(candidatePos, ray, shapes, drawingManager.drawPoints, SNAP_THRESHOLD, e.intersections[0]);

          let finalPos = candidatePos;
          let activeSnap = null;

          // Only prioritize specific geometry snaps over the inferred plane
          if (snap && ['vertex', 'midpoint', 'edge', 'endpoint', 'face'].includes(snap.type)) {
              finalPos = snap.position;
              activeSnap = snap;
          } else {
              if (inferredPlane) {
                  finalPos = candidatePos;
                  activeSnap = null; // Don't show snap indicator if just locking to plane
              } else {
                  if (snap) {
                      finalPos = snap.position;
                      activeSnap = snap;
                  }
              }
          }

          drawingManager.setSnapInfo(activeSnap);

          // Update Cursor
          if (drawingManager.drawPoints.length > 0) {
              const lastPt = drawingManager.drawPoints[drawingManager.drawPoints.length - 1];
              if (lastPt) {
                const currentPos = finalPos;
                const dx = Math.abs(currentPos.x - lastPt.x);
                const dz = Math.abs(currentPos.z - lastPt.z);

                const isGeometrySnap = activeSnap && ['vertex', 'midpoint', 'edge', 'endpoint'].includes(activeSnap.type);

                if (!isGeometrySnap) {
                    // Respect inferred plane Y if set
                    const lockedY = inferredPlane ? candidatePos.y : currentPos.y; 

                    if (dx < ALIGN_THRESHOLD) {
                        drawingManager.setInferenceGuide({ type: 'x', start: new THREE.Vector3(lastPt.x, 0, lastPt.z), end: new THREE.Vector3(lastPt.x, 0, currentPos.z) });
                        drawingManager.setCursorPos(new THREE.Vector3(lastPt.x, lockedY, currentPos.z));
                    } else if (dz < ALIGN_THRESHOLD) {
                        drawingManager.setInferenceGuide({ type: 'z', start: new THREE.Vector3(lastPt.x, 0, lastPt.z), end: new THREE.Vector3(currentPos.x, 0, lastPt.z) });
                        drawingManager.setCursorPos(new THREE.Vector3(currentPos.x, lockedY, lastPt.z));
                    } else {
                        drawingManager.setInferenceGuide(null);
                        drawingManager.setCursorPos(finalPos);
                    }
                } else {
                    drawingManager.setInferenceGuide(null);
                    drawingManager.setCursorPos(finalPos);
                }
              }
          } else {
              drawingManager.setCursorPos(finalPos);
          }
      } else {
          drawingManager.setSnapInfo(null);
      }
  }, [tool, shapes, drawingManager, isGizmoDragging, isPPDragging, ppState, rotateState, handlePPMove, handleRotateMove]);

  return (
    <>
        <color attach="background" args={['#f1f5f9']} />

        <ambientLight intensity={0.7} />
        <directionalLight position={[10, 20, 10]} intensity={1} castShadow shadow-mapSize={[2048, 2048]} />
        <hemisphereLight args={['#ffffff', '#000000', 0.5]} />

        <Grid infiniteGrid sectionColor="#cbd5e1" cellColor="#e2e8f0" sectionSize={1} cellSize={0.1} fadeDistance={50} position={[0, -0.01, 0]} />
        <axesHelper args={[5]} />

        <GuideLinesRenderer lines={guideLines} />
        <AlignmentLinesRenderer lines={alignmentLines} />
        <CameraHandler view={currentView} onFinished={() => setCurrentView(null)} />

        <OrbitControls makeDefault enabled={!drawingManager.isDragging && !isGizmoDragging && !isPPDragging && rotateState.phase !== 'rotating'} maxPolarAngle={Math.PI / 2 - 0.05} />

        <group 
            onPointerDown={(e) => {
                if (tool === ToolType.ROTATE) handleRotateClick(e);
                else if (tool === ToolType.SELECT) { 
                }
                else if (tool !== ToolType.PUSH_PULL) drawingManager.handlePointerDown(e);
            }} 
            onPointerUp={(e) => { 
                if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE) drawingManager.handlePointerUp(e); 
                if (tool === ToolType.PUSH_PULL) handlePPUp(); 
            }}
            onClick={(e) => {
                 if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE) drawingManager.handleClick(e);
            }}
            onPointerMove={(e) => { 
                if (tool === ToolType.PUSH_PULL) handlePPMove(e); 
                if (tool === ToolType.ROTATE) handleRotateMove(e);
                else handlePointerMove(e);
            }}
        >
          <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow>
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial visible={false} />
          </mesh>
        </group>

        <group>
          {shapes.map((shape) => (
             <ShapeRenderer
                key={shape.id}
                shape={shape}
                isSelected={selectedIds.includes(shape.id)}
                pushPullState={ppState}
                pushPullHandlers={{ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }}
                drawingHandlers={drawingManager}
                rotateHandlers={{ handleClick: handleRotateClick, handlePointerMove: handleRotateMove }}
                setDraggingState={() => {}} 
                onShapeRef={handleShapeRef}
                shapeRefs={shapeRefs}
                setAlignmentLines={setAlignmentLines}
              />
          ))}
          {ppTempShape && (
              <ShapeRenderer
                shape={ppTempShape}
                isSelected={false}
                pushPullState={ppState}
                pushPullHandlers={{ handlePointerDown: () => {}, handlePointerUp: () => {}, handlePointerMove: () => {} }}
                drawingHandlers={drawingManager}
                rotateHandlers={{ handleClick: () => {}, handlePointerMove: () => {} }}
                setDraggingState={() => {}}
                onShapeRef={() => {}}
                shapeRefs={shapeRefs}
                setAlignmentLines={() => {}}
              />
          )}
        </group>

        <InteractionLayer 
            shapes={shapes} 
            tool={tool} 
            setCursorPos={drawingManager.setCursorPos} 
            setSnapInfo={drawingManager.setSnapInfo} 
            cursorPos={drawingManager.cursorPos} 
            snapInfo={drawingManager.snapInfo} 
            drawPoints={drawingManager.drawPoints} 
            isDragging={drawingManager.isDragging} 
            drawingHeight={drawingManager.drawingHeight} 
            typedInput={drawingManager.typedInput} 
            guideCreating={drawingManager.guideCreation} 
            rotateState={rotateState} 
            drawingNormal={drawingManager.drawingNormal} 
            isGizmoDragging={isGizmoDragging} 
            inferenceGuide={drawingManager.inferenceGuide} 
            setInferenceGuide={drawingManager.setInferenceGuide} 
            onPointerDown={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE) drawingManager.handlePointerDown(e); }}
            onPointerUp={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE) drawingManager.handlePointerUp(e); }}
            onClick={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && tool !== ToolType.ROTATE) drawingManager.handleClick(e); }}
            onMove={handlePointerMove}
        />

        <SelectionGizmo setDragging={setGizmoDragging} />
        <GizmoHelper alignment="bottom-left" margin={[80, 80]}><GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" /></GizmoHelper>
    </>
  );
};

const Viewport: React.FC = () => {
    const appState = useApp();
    return (
        <div className="w-full h-full bg-slate-50 relative">
            <Canvas 
                shadows 
                camera={{ position: [8, 12, 12], fov: 45 }} 
                gl={{ preserveDrawingBuffer: true, antialias: true }}
            >
                <AppContext.Provider value={appState}>
                    <SceneContent />
                </AppContext.Provider>
            </Canvas>
        </div>
    );
};

export default Viewport;
